ALTER TABLE public.attendance ADD COLUMN IF NOT EXISTS late_minutes integer;
ALTER TABLE public.cms_settings ADD COLUMN IF NOT EXISTS is_public boolean NOT NULL DEFAULT false;
ALTER TABLE public.face_scan_logs ADD COLUMN IF NOT EXISTS geometry_score real, ADD COLUMN IF NOT EXISTS match_engine text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS signature_url text;
ALTER TABLE public.staff_leaves ADD COLUMN IF NOT EXISTS leave_scope text NOT NULL DEFAULT 'full_day';
ALTER TABLE public.students ADD COLUMN IF NOT EXISTS sis_sync_version integer DEFAULT 0, ADD COLUMN IF NOT EXISTS sis_last_synced_at timestamptz;
ALTER TABLE public.subject_score_columns ADD COLUMN IF NOT EXISTS homework_assignment_id uuid;
ALTER TABLE public.notifications ADD COLUMN IF NOT EXISTS push_sent boolean NOT NULL DEFAULT false;
ALTER TABLE public.personnel_face_descriptors ADD COLUMN IF NOT EXISTS texture real[];
ALTER TABLE public.kiosk_devices ADD COLUMN IF NOT EXISTS device_key text, ADD COLUMN IF NOT EXISTS name text, ADD COLUMN IF NOT EXISTS default_direction text NOT NULL DEFAULT 'in', ADD COLUMN IF NOT EXISTS agent_version text, ADD COLUMN IF NOT EXISTS platform text, ADD COLUMN IF NOT EXISTS disk_free_mb integer, ADD COLUMN IF NOT EXISTS camera_ok boolean, ADD COLUMN IF NOT EXISTS door_ok boolean, ADD COLUMN IF NOT EXISTS health_note text, ADD COLUMN IF NOT EXISTS is_active boolean NOT NULL DEFAULT true;
CREATE TABLE IF NOT EXISTS public.app_settings (key text PRIMARY KEY, value jsonb, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.app_settings TO authenticated;
GRANT ALL ON public.app_settings TO service_role;
ALTER TABLE public.app_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY recovery_admin_settings ON public.app_settings TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE IF NOT EXISTS public.cold_storage_registry (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), bucket_name text NOT NULL, file_path text NOT NULL, drive_file_id text NOT NULL, drive_web_link text, mime_type text, size_bytes bigint DEFAULT 0, offloaded_at timestamptz DEFAULT now(), created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now(), UNIQUE(bucket_name,file_path));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.cold_storage_registry TO authenticated;
GRANT ALL ON public.cold_storage_registry TO service_role;
ALTER TABLE public.cold_storage_registry ENABLE ROW LEVEL SECURITY;
CREATE POLICY recovery_admin_registry ON public.cold_storage_registry TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE IF NOT EXISTS public.dim_date (date date PRIMARY KEY, day integer NOT NULL, month integer NOT NULL, quarter integer NOT NULL, is_holiday boolean NOT NULL DEFAULT false, academic_year text, semester integer);
GRANT SELECT ON public.dim_date TO authenticated;
GRANT ALL ON public.dim_date TO service_role;
ALTER TABLE public.dim_date ENABLE ROW LEVEL SECURITY;
CREATE POLICY recovery_calendar_read ON public.dim_date FOR SELECT TO authenticated USING (true);
CREATE TABLE IF NOT EXISTS public.kiosk_agent_alerts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), device_id text, device_name text, kind text NOT NULL DEFAULT 'unknown_face', snapshot_url text, note text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.kiosk_agent_alerts TO authenticated;
GRANT ALL ON public.kiosk_agent_alerts TO service_role;
ALTER TABLE public.kiosk_agent_alerts ENABLE ROW LEVEL SECURITY;
CREATE POLICY recovery_admin_kiosk_alerts ON public.kiosk_agent_alerts TO authenticated USING (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'director')) WITH CHECK (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'director'));
CREATE TABLE IF NOT EXISTS public.kiosk_live_frames (device_id text PRIMARY KEY, image text, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.kiosk_live_frames TO authenticated;
GRANT ALL ON public.kiosk_live_frames TO service_role;
ALTER TABLE public.kiosk_live_frames ENABLE ROW LEVEL SECURITY;
CREATE POLICY recovery_admin_kiosk_frames ON public.kiosk_live_frames TO authenticated USING (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'director')) WITH CHECK (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'director'));
CREATE TABLE IF NOT EXISTS public.observation_rubrics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL DEFAULT 'OBEC 5 ขั้นตอนการจัดการเรียนรู้', description text, criteria jsonb NOT NULL DEFAULT '[]'::jsonb, is_active boolean DEFAULT true, created_at timestamptz DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.observation_rubrics TO authenticated;
GRANT ALL ON public.observation_rubrics TO service_role;
ALTER TABLE public.observation_rubrics ENABLE ROW LEVEL SECURITY;
CREATE POLICY recovery_rubrics_read ON public.observation_rubrics FOR SELECT TO authenticated USING (true);
CREATE POLICY recovery_rubrics_admin ON public.observation_rubrics FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE IF NOT EXISTS public.storage_tier_policies (bucket text PRIMARY KEY, enabled boolean NOT NULL DEFAULT true, older_than_days integer NOT NULL DEFAULT 90, keep_recent integer NOT NULL DEFAULT 0, note text, updated_at timestamptz NOT NULL DEFAULT now(), quota_mb integer, priority integer NOT NULL DEFAULT 100, dedupe_drive boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.storage_tier_policies TO authenticated;
GRANT ALL ON public.storage_tier_policies TO service_role;
ALTER TABLE public.storage_tier_policies ENABLE ROW LEVEL SECURITY;
CREATE POLICY recovery_admin_storage_policy ON public.storage_tier_policies TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE IF NOT EXISTS public.system_credentials (key text PRIMARY KEY, value text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.system_credentials TO service_role;
ALTER TABLE public.system_credentials ENABLE ROW LEVEL SECURITY;